import re
from decimal import Decimal
from fractions import Fraction

MAX_AMOUNT = Fraction(1000000)
_STRING_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)


def _to_exact_fraction(value):
    """Convert a validated input to an exact Fraction without consulting decimal context."""
    if isinstance(value, bool):
        raise ValueError("bool is not an allowed amount type")
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError("non-finite amount")
        return Fraction(value)  # exact conversion, independent of context
    if isinstance(value, int):
        return Fraction(value)
    if isinstance(value, str):
        if not _STRING_RE.fullmatch(value):
            raise ValueError(f"invalid amount string: {value!r}")
        return Fraction(Decimal(value))  # Decimal(str) is exact
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def _check_cents_amount(amount):
    """Validate a positive Fraction amount representable exactly in cents and <= MAX_AMOUNT."""
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount exceeds 1000000.00")
    cents = amount * 100
    if cents.denominator != 1:
        raise ValueError("amount is not exactly representable in cents")
    return cents.numerator


def _cents_to_decimal(cents):
    # Decimal built from a string is exact and independent of the context precision.
    return Decimal(f"{cents}E-2")


def parse_amount(value):
    fraction = _to_exact_fraction(value)
    cents = _check_cents_amount(fraction)
    return _cents_to_decimal(cents)


def format_amount(value):
    return format(value, ".2f")
EOF
